def parse_duration(text):
    text = text.strip()

    if not text:
        return None

    # Pure number means seconds
    if text.isdigit():
        return int(text)

    # Find all numeric-unit pairs
    matches = re.findall(r'(\d+)([hms])', text)

    if not matches:
        return None

    # Check order of units: h must come before m, m before s
    h_idx = text.find('h')
    m_idx = text.find('m')
    s_idx = text.find('s')

    if h_idx >= 0 and m_idx >= 0 and h_idx > m_idx:
        return None
    if m_idx >= 0 and s_idx >= 0 and m_idx > s_idx:
        return None

    # Check that nothing remains after the last unit
    last_unit_idx = max(h_idx, m_idx, s_idx)

    # If no units found at all, return None
    if last_unit_idx < 0:
        return None

    after = text[last_unit_idx + 1:]
    if after and not after.isdigit():
        return None
    # Any remaining digits after the last unit have no unit
    if after:
        return None

    # Calculate total seconds
    total = 0
    for num_str, unit in matches:
        num = int(num_str)
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num

    return total
